using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerTests()
        {
            _context = TestDbContext.Create();
            SeedData(_context);
            _controller = new InstructorsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private static void SeedData(SchoolContext context)
        {
            var dept = new Department { DepartmentID = 1, Name = "CS", Budget = 100000, StartDate = DateTime.Now };
            context.Departments.Add(dept);

            var course1 = new Course { CourseID = 101, Title = "Intro to CS", Credits = 3, DepartmentID = 1, Enrollments = new List<Enrollment>() };
            var course2 = new Course { CourseID = 102, Title = "Data Structures", Credits = 4, DepartmentID = 1, Enrollments = new List<Enrollment>() };
            context.Courses.AddRange(course1, course2);

            var instructor1 = new Instructor
            {
                ID = 1,
                LastName = "Fakhouri",
                FirstMidName = "Fadi",
                HireDate = new DateTime(2010, 3, 15),
                OfficeAssignment = new OfficeAssignment { InstructorID = 1, Location = "Room 101" },
                CourseAssignments = new List<CourseAssignment>
                {
                    new CourseAssignment { InstructorID = 1, CourseID = 101 }
                }
            };
            var instructor2 = new Instructor
            {
                ID = 2,
                LastName = "Zheng",
                FirstMidName = "Roger",
                HireDate = new DateTime(2015, 7, 1),
                CourseAssignments = new List<CourseAssignment>()
            };
            context.Instructors.AddRange(instructor1, instructor2);
            context.SaveChanges();
        }

        [Fact]
        public void Index_NoParams_ReturnsViewWithInstructors()
        {
            var result = _controller.Index(null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.Equal(2, model.Instructors.Count());
        }

        [Fact]
        public void Index_WithInstructorId_PopulatesCourses()
        {
            var result = _controller.Index(1, null) as ViewResult;

            var model = Assert.IsType<InstructorIndexData>(result!.Model);
            Assert.NotNull(model.Courses);
            Assert.Single(model.Courses);
            Assert.Equal("Intro to CS", model.Courses.First().Title);
        }

        [Fact]
        public void Index_WithCourseId_PopulatesEnrollments()
        {
            // Add an enrollment
            _context.Enrollments.Add(new Enrollment { EnrollmentID = 1, StudentID = 0, CourseID = 101, Grade = Grade.A });
            _context.SaveChanges();

            var result = _controller.Index(1, 101) as ViewResult;

            var model = Assert.IsType<InstructorIndexData>(result!.Model);
            Assert.NotNull(model.Enrollments);
        }

        [Fact]
        public void Details_ValidId_ReturnsInstructor()
        {
            var result = _controller.Details(1) as ViewResult;

            Assert.NotNull(result);
            var instructor = Assert.IsType<Instructor>(result.Model);
            Assert.Equal("Fakhouri", instructor.LastName);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
        }

        [Fact]
        public void Details_InvalidId_ReturnsNotFound()
        {
            var result = _controller.Details(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Create_Get_ReturnsViewWithCourseData()
        {
            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            var instructor = Assert.IsType<Instructor>(result.Model);
            Assert.NotNull(instructor.CourseAssignments);
        }

        [Fact]
        public void Create_Post_ValidInstructor_RedirectsToIndex()
        {
            var instructor = new Instructor
            {
                LastName = "NewLast",
                FirstMidName = "NewFirst",
                HireDate = new DateTime(2023, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = _controller.Create(instructor, null) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Equal(3, _context.Instructors.Count());
        }

        [Fact]
        public void Create_Post_WithSelectedCourses_AssignsCourses()
        {
            var instructor = new Instructor
            {
                LastName = "CourseInstructor",
                FirstMidName = "Test",
                HireDate = new DateTime(2023, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = _controller.Create(instructor, new[] { "101", "102" }) as RedirectToActionResult;

            Assert.NotNull(result);
            var saved = _context.Instructors.First(i => i.LastName == "CourseInstructor");
            Assert.Equal(2, _context.CourseAssignments.Count(ca => ca.InstructorID == saved.ID));
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            _controller.ModelState.AddModelError("LastName", "Required");
            var instructor = new Instructor
            {
                FirstMidName = "Test",
                HireDate = DateTime.Now,
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = _controller.Create(instructor, null) as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
